fn days_to_next_sunday(day: &str) -> i8 {
    let idx: i8 = match day {
        "SUN" => 0,
        "MON" => 1,
        "TUE" => 2,
        "WED" => 3,
        "THU" => 4,
        "FRI" => 5,
        "SAT" => 6,
        _ => unreachable!("Input is guaranteed to be a valid day abbreviation"),
    };

    // Days until next Sunday; for Sunday itself we must return 7.
    let delta = (7 - idx) % 7;
    if delta == 0 { 7 } else { delta }
}

